"""Generate ANALYSIS.md from the evidence outputs in data/processed/.
Inputs : region_stats.csv, nr2_published_points.csv, deep_dive_nr2.json, robustness.json
Produced by data-raw/analysis_regions.R and data-raw/analysis_robustness.R."""
import csv, json, pathlib
root = pathlib.Path(__file__).resolve().parents[1]; P = root / "data" / "processed"
rb = json.load(open(P / "robustness.json")); dd = json.load(open(P / "deep_dive_nr2.json"))
pts = list(csv.DictReader(open(P / "nr2_published_points.csv")))
rs = list(csv.DictReader(open(P / "region_stats.csv")))
f = lambda x, n=1: f"{float(x):.{n}f}"
R = rb["regions"]; S = rb["sites"]; sa = {r["region"]: r for r in R["suitable_area"]}
L = []; w = L.append
w("# Evidence: how far can the comparison be trusted?\n")
w("> **We compare potential landing areas by terrain, illumination and Earth visibility.**\n")
w(f"_Generated by `data-raw/build_analysis_report.py` from `data/processed/` (robustness run {rb['generated_utc']}, deep dive {dd['generated_utc']}). Do not edit by hand._\n")
w("Two checks back the comparison: (1) whether the ranking survives changed assumptions, and (2) a detailed comparison of one region against the original rasters and a published site analysis.\n")
w("## 1  Robustness\n")
w(f"**Regions.** {R['scenarios']:,} scenarios: weights for terrain, illumination and Earth visibility drawn {R['weights']}, each combined with slope limits {', '.join(str(x) for x in R['slope_limits_deg'])}°. Region score = weighted mean of the share of LOLA 80 m pixels below the slope limit, mean Sun visibility and mean Earth visibility (Mazarico 120 m), computed on the original pixels inside each USGS 2024 outline.\n")
w("| Region | P(rank 1) | P(top 3) | Median rank | 5–95 % rank | Suitable area, median (5–95 %) |\n|---|---:|---:|---:|---:|---:|")
for r in R["table"]:
    s = sa[r["region"]]
    w(f"| {r['region']} | {f(r['p_rank1'])} % | {f(r['p_top3'])} % | {r['median_rank']} | {r['rank_p05']}–{r['rank_p95']} | {f(s['suitable_share_median'],0)} % ({f(s['suitable_share_p05'],0)}–{f(s['suitable_share_p95'],0)}) |")
w("\nSuitable area = share of the region's ~1.5 km cells scoring ≥ 50 (2,000 scenarios).\n")
w("Rank with equal weights, by slope limit:\n")
w("| Region | " + " | ".join(f"< {x}°" for x in R["slope_limits_deg"]) + " |\n|---|" + "---:|" * len(R["slope_limits_deg"]))
for r in R["by_slope_limit"]:
    w(f"| {r['region']} | " + " | ".join(str(r[f'limit_{x}']) for x in R["slope_limits_deg"]) + " |")
w(f"\n**Candidate points.** {S['scenarios']:,} scenarios: the same weightings and slope limits applied to the landing score of each published point (flat ground within 1 km, long-term Sun and Earth with terrain, measured on every original pixel within 1 km). The score is absolute, so ranks change only through the assumptions, never through which places are compared.\n")
w("| Point | P(rank 1) | P(top 2) | Median rank | 5–95 % rank |\n|---|---:|---:|---:|---:|")
for r in S["table"]:
    w(f"| {r['name']} | {f(r['p_rank1'])} % | {f(r['p_top2'])} % | {r['median_rank']} | {r['rank_p05']}–{r['rank_p95']} |")
t = R["table"]; vol = max(t, key=lambda r: r["rank_p95"] - r["rank_p05"])
w(f"\n**Reading.** {t[0]['region']} is the robust leader (rank 1 in {f(t[0]['p_rank1'])} %, top 3 in {f(t[0]['p_top3'])} %). {vol['region']} is the most assumption-sensitive region (rank {vol['rank_p05']}–{vol['rank_p95']}); it wins only when flat terrain dominates the weighting. Among points, {S['table'][0]['name']} leads in {f(S['table'][0]['p_rank1'])} % of scenarios.\n")
w("## 2  Deep dive: Nobile Rim 2\n")
w(f"Reference: {dd['published_source']}, Table 3, the {dd['earth']['n']} Nobile Rim 2 locations. All {dd['inside_2024_outline']} lie inside the USGS 2024 outline (McClernan et al. 2024). Each was re-evaluated on LOLA LDSM 80 m slope and Mazarico et al. AVGVISIB 120 m Sun/Earth visibility.\n")
w(f"- Earth visibility: Pearson r = {dd['earth']['pearson_r']}, mean |Δ| = {dd['earth']['mean_abs_diff_pp']} pp, max {dd['earth']['max_abs_diff_pp']} pp.")
w(f"- Illumination × shadow criterion (C3): Spearman ρ = {dd['c3']['spearman_rho']}, Pearson r = {dd['c3']['pearson_r']}.")
w(f"- Slope: {dd['slope']['points_below_5deg_100m_max']} of {dd['slope']['n']} points stay below 5° within 100 m in our 80 m data.\n")
w("| ID | Their rank | Lat | Lon | Earth publ. | Earth ours | Δ pp | Slope point | Max ≤ 100 m | C3 publ. | C3 ours |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|")
for p in pts:
    w(f"| {p['id']} | {p['pena_rank']} | {p['lat']} | {p['lon']} | {f(p['pena_earth_pct'])} % | {f(p['earth_pct_ours_120m'])} % | {float(p['earth_diff_pp']):+.1f} | {f(p['slope_point_80m'])}° | {f(p['slope_max_100m'])}° | {float(p['pena_c3']):,.0f} | {float(p['c3_ours']):,.0f} |")
w("\n### Why the numbers differ\n")
w("1. **Resolution of the same product.** The paper samples the 240 m Earth-visibility map, we the 120 m map (bilinear). Published values are digital numbers; 25,000 DN = 100 % (PDS label scaling 0.00004). Differences ≤ 1.9 pp.")
w("2. **Definition of permanent shadow.** We mark PSR as Sun DN = 0 on the 120 m map within 2 km; the paper uses a 240 m PSR map. Finer pixels resolve more small shadowed pockets, so our C3 is ~10–15 % higher while the ranking is preserved (ρ ≈ 0.96).")
w("3. **DEM resolution (ID 995).** The paper's slope filter used a 5 m LOLA DEM with landing polygons down to 25 m². Such a patch is not resolved at 80 m, where we see 17°. The point also has 0 % Earth visibility in both datasets.")
w("4. **Point vs. region.** The paper's optimum (ID 358) is flat with ~33 % Earth visibility, yet the region as a whole is rough and ranks mid-field in the robustness test. A 20–30 km region can contain an excellent spot while being average overall.\n")
w("### App grid vs. original pixels (all nine regions)\n")
w("| Region | Area km² | Slope median raw / grid | < 8° raw / grid | Sun raw / grid | Earth raw / grid | PSR raw / grid |\n|---|---:|---:|---:|---:|---:|---:|")
for r in rs:
    w(f"| {r['region']} | {r['area_km2']} | {f(r['raw_slope_median'])}° / {f(r['grid_slope_median'])}° | {f(r['raw_flat_lt8'])} / {f(r['grid_flat_lt8'])} % | {f(r['raw_sun_mean'])} / {f(r['grid_sun_mean'])} % | {f(r['raw_earth_mean'])} / {f(r['grid_earth_mean'])} % | {f(r['raw_psr_pct'])} / {f(r['grid_psr_pct'])} % |")
md = lambda a, b: max(abs(float(r[a]) - float(r[b])) for r in rs)
w(f"\nMaximum difference: {md('raw_slope_median','grid_slope_median'):.2f}° median slope, {md('raw_flat_lt8','grid_flat_lt8'):.1f} pp flat share, {md('raw_sun_mean','grid_sun_mean'):.1f} pp Sun, {md('raw_earth_mean','grid_earth_mean'):.1f} pp Earth. The ~1.5 km display grid does not change the comparison.\n")
dzf = P / "dossiers.json.gz"
if dzf.exists():
    import gzip
    dz = json.load(gzip.open(dzf))["points"]
    w("## 3  Check against real landings\n")
    w("The original rasters read at the measured landing positions (NASA NSSDCA lander table, LROC measurements):\n")
    w("| Mission | LOLA slope at point | Steepest within 100 m | Sun, long-term | Earth, long-term | Outcome |\n|---|---:|---:|---:|---:|---|")
    for k, o in [("im1", "tipped over; ~12° slope reported (Thomson et al. 2025, EGU25-20315)"), ("im2", "tipped over in a small crater"), ("change7", "planned (2027)")]:
        if k in dz:
            q = dz[k]["point"]
            w(f"| {dz[k]['name']} | {q['slope']}° | {q['slope_max_100m']}° | {q['sun']} % | {q['earth']} % | {o} |")
    w("\nIM-1: our 80 m value agrees with the reported slope, and the terrain criterion would have flagged the site. IM-2: the hazard was smaller than one 80 m pixel, which is the main limitation of an area-level comparison.\n")
vcf = P / "validation_checks.json"
if vcf.exists():
    vc = json.load(open(vcf)); n = vc["nasa_regions"]; c = vc["consistency"]
    w("## 4  Does the score see what NASA saw?\n")
    w(f"NASA selected nine Artemis regions with partly different criteria (science value, mission design). On the app grid (~1.5 km cells, equal weights, 8°) and within the same latitude band ({abs(n['lat_band'][1])} to {abs(n['lat_band'][0])}° S), cells inside the regions score higher than the rest: median {n['median_inside']} vs {n['median_outside']}, {n['share_inside_above_50']} % vs {n['share_outside_above_50']} % of cells above 50, AUC {n['auc']} (Wilcoxon p = {n['wilcoxon_p']:.1e}; {n['n_inside']:,} vs {n['n_outside']:,} cells).\n")
    w("| Criterion (median per cell) | Inside NASA regions | Rest of the band |\n|---|---:|---:|")
    for k, lab in [("flat_lt8", "Flat ground below 8°"), ("sun", "Sunlight, long-term"), ("earth", "Earth in view, long-term")]:
        w(f"| {lab} | {n['per_criterion'][k]['inside']} % | {n['per_criterion'][k]['outside']} % |")
    w("\nNASA's regions trade flat ground for light and Earth visibility: they sit on elevated rims and massifs. The separation is real but moderate (AUC 0.5 = none, 1 = perfect), as expected when NASA weighs criteria we do not model.\n")
    w("## 5  Internal consistency: two code paths\n")
    w("`build_terrain.R` (stratified samples) and `build_dossiers.R` (every 80 m pixel) were written separately. Within 1 km of each site:\n")
    w("| Site | Mean slope, terrain / dossier | Δ | Flat below 8°, terrain / dossier | Δ |\n|---|---:|---:|---:|---:|")
    for r in c["rows"]:
        w(f"| {r['name']} | {r['slope_mean_terrain']}° / {r['slope_mean_dossier']}° | {r['d_slope']:+.2f}° | {r['flat8_terrain']} / {r['flat8_dossier']} % | {r['d_flat8']:+.1f} pp |")
    w(f"\nMaximum difference {c['max_abs_d_slope']}° and {c['max_abs_d_flat8']} pp.\n")
    eph = json.load(open(P / "ephemeris_validation.json"))
    w("## 6  Ephemeris\n")
    w(f"DE421 Sun and Earth directions ({eph['n_epochs']:,} hourly epochs 2026 to 2030) agree with the independent IAU 2015 rotation model within {max(eph['de421_vs_iau2015_sun_direction_max_deg'], eph['de421_vs_iau2015_earth_direction_max_deg'])}° (tolerance {eph['expected']['de421_vs_iau_tolerance_deg']}°). Libration in latitude {eph['subearth_latitude_range_deg']}° and longitude {eph['subearth_longitude_range_deg']}° and the Earth-Moon distance {eph['earth_moon_distance_range_km']} km lie in their physical ranges; the total lunar eclipse of 3 March 2026 is reproduced.\n")
w("## Limitations\n")
w("- Long-term averages (Mazarico et al. 2011, multi-year); seasonal and mission-window effects are covered only for the five candidate points.")
w("- 80 m slope cannot resolve lander-scale hazards (boulders, < 100 m craters); final site certification needs 5 m / 1 m LOLA and LROC NAC data.")
w("- The weights express preferences, not truth, which is why we report the distribution of ranks instead of one ranking.\n")
w("## Reproduce\n\n```\nRscript data-raw/build_terrain.R\nRscript data-raw/analysis_regions.R\nRscript data-raw/analysis_robustness.R\nRscript data-raw/build_dossiers.R\nRscript data-raw/build_validation.R\npython3 data-raw/build_analysis_report.py\npython3 data-raw/build_provenance_doc.py\n```\nOriginal rasters go in `data-raw/input/` (see its README).")
(root / "ANALYSIS.md").write_text("\n".join(L) + "\n"); print("ANALYSIS.md", len(L), "lines")
